    if horizontal_spine:
        spine = best_row
        positions = [c for r, c in points if r == spine]
        for r, c in points:
            for rr in range(min(r, spine), max(r, spine) + 1):
                if out[rr][c] == 0:
                    out[rr][c] = 3
        for c in range(min(positions), max(positions) + 1):
            if out[spine][c] == 0:
                out[spine][c] = 3
    else:
        spine = best_col
        positions = [r for r, c in points if c == spine]
